import { type BrandId,ProductLogo } from "@krizaka/ui";

import { format, getDictionary, type Locale } from "@/lib/i18n";

/** The brand library on the Krizaka CDN (Bunny Storage `brand/`), generated by tools/export-brand.mjs. */
const LIBRARY = "https://krizaka-assets.b-cdn.net/brand";

const MARKS: BrandId[] = ["krizaka", "orazaka", "orochia", "yasakia", "yororis", "yomizaka", "kachizaka", "akinaza"];
/** The scope each mark wears (the brand's colours), spelled out so the class is a literal. */
const SCOPE: Record<BrandId, string> = { krizaka: "brand-krizaka", orazaka: "brand-orazaka", orochia: "brand-orochia", yasakia: "brand-yasakia", yororis: "brand-yororis", yomizaka: "brand-yomizaka", kachizaka: "brand-kachizaka", akinaza: "brand-akinaza" };

/* /docs/ui/brand-marks — the eight marks of the Krizaka family, drawn by @krizaka/ui (the same component the products and
   this site's navigation use). Nothing is copied here: the marks are rendered, never re-drawn. */
export function BrandMarksDoc({ locale }: { locale: Locale }) {
  const x = getDictionary(locale).docs.ia.brand;
  return (
    <div>
      <p>{x.intro}</p>
      <ul className="kz-brand-marks not-prose">
        {MARKS.map((id) => (
          <li key={id} className={SCOPE[id]}>
            <ProductLogo id={id} size={96} title={format(x.mark, { name: id.charAt(0).toUpperCase() + id.slice(1), role: x[id] })} />
            <span>{id.charAt(0).toUpperCase() + id.slice(1)}</span>
            <span className="kz-docs-note">{x[id]}</span>
            <span className="kz-docs-note">
              <a href={`${LIBRARY}/${id}/logo-dark.svg`} download>{x.svgDark}</a> · <a href={`${LIBRARY}/${id}/logo-light.svg`} download>{x.svgLight}</a> ·{" "}
              <a href={`${LIBRARY}/${id}/logo-dark-1024.png`} download>{x.png}</a> · <a href={`${LIBRARY}/${id}/avatar-1024.png`} download>{x.avatar}</a> ·{" "}
              <a href={`${LIBRARY}/${id}/social-preview-1280x640.png`} download>{x.social}</a>
            </span>
          </li>
        ))}
      </ul>
      <p className="kz-docs-note">{x.use}</p>
      <p className="kz-docs-note">
        <b>{x.downloads}.</b> {x.note} <a href={`${LIBRARY}/manifest.json`}>{x.manifest}</a>
      </p>
    </div>
  );
}
